546	  /// `signalProcess: false` is for the one caller (`reapChildren`) that already knows — via a
547	  /// `waitpid` call that JUST returned this same pid — that the process is dead. Sending it a
548	  /// signal at that point isn't merely redundant: `waitpid` reaping a zombie releases its pid back
549	  /// to the OS's available pool immediately, so a `killpg`/`kill` issued after that reap targets
550	  /// WHATEVER process the OS may have already recycled that pid number to, not the session's shell.
551	  /// Every other caller signals a process it hasn't just reaped itself, so the default stays `true`.
552	  private func closeMaster(_ session: PTYSession, signalProcess: Bool = true) {
553	    guard session.masterDescriptor >= 0 else { return }
554	    sessionsByMaster.removeValue(forKey: session.masterDescriptor)
555	    SessionIO.close(session.masterDescriptor)
556	    session.masterDescriptor = -1
557	    session.isEnding = true
558	    if signalProcess {
559	      SessionPTY.terminate(processID: session.processID)
560	    }
561	  }
