563	  @discardableResult
564	  private func endSession(
565	    _ session: PTYSession, status: Int32, force: Bool = false, signalProcess: Bool = true
566	  ) -> Bool {
567	    // On the force path, the process-tree snapshot that finds a setsid-detached descendant must be
568	    // taken BEFORE anything can kill the session's shell out from under it — `closeMaster`
569	    // unconditionally closes the pty's master descriptor, and closing a pty's last open master fd
570	    // is itself a kernel-generated hangup (SIGHUP to the foreground process group) regardless of
571	    // the `signalProcess` flag, which only gates our own EXPLICIT killpg call. So the snapshot
572	    // (`terminationTargets`) runs first; closeMaster runs right after it, and that same fast kernel
573	    // hangup is left to kill the shell in the common case, same as before this existed. Measured:
574	    // making forceTerminate's own SIGTERM/SIGKILL loop the ONLY thing killing the shell (by moving
575	    // closeMaster fully after it) made an ordinary, non-detached kill occasionally exceed the
576	    // loop's retry budget under load and get reported as a failed stop — reordering back to this
577	    // (snapshot first, then the fast hangup) is what resolved that without shrinking the snapshot's
578	    // correctness window.
579	    guard !force else {
580	      let targets = SessionPTY.terminationTargets(for: [session.processID])
581	      closeMaster(session, signalProcess: false)
582	      guard SessionPTY.forceTerminate(targets: targets).isEmpty else {
583	        SessionLog.write("failed to stop session \(session.identifier.uuidString)")
584	        return false
585	      }
586	      finishSession(session, status: status)
587	      return true
588	    }
589	    closeMaster(session, signalProcess: signalProcess)
590	    finishSession(session, status: status)
591	    return true
592	  }
