596	    // comment for why the snapshot must be taken before closeMaster runs.
597	    let targets = SessionPTY.terminationTargets(for: endingSessions.map(\.processID))
598	    for session in endingSessions { closeMaster(session, signalProcess: false) }
599	    let failedProcessIDs = SessionPTY.forceTerminate(targets: targets)
600	    for session in endingSessions where !failedProcessIDs.contains(session.processID) {
601	      finishSession(session, status: status)
602	    }
603	    for session in endingSessions where failedProcessIDs.contains(session.processID) {
604	      SessionLog.write("failed to stop session \(session.identifier.uuidString)")
605	    }
606	    return failedProcessIDs.isEmpty
607	  }
