func (c *Config) AddProject(parentPath, vcs string) error {
	return c.withLock(func() error {
		data, err := c.Read()
		if err != nil {
			return err
		}
		if project, ok := data[parentPath].(map[string]any); ok {
			project["vcs"] = vcs
