func (s *Service) effectiveVCS(path, stored string, persist bool) string {
	v, err := vcs.Detect(path)
	if err != nil {
		return stored
	}
	detected := string(v.Type())
	if detected != stored && persist {
		_ = s.Config.SetProjectVCS(path, detected)
	}
