		vcsType := s.effectiveVCS(projectPath, project.VCS, true)
		vcsSet := s.vcsWorkspaceSet(projectPath, vcsType)
		s.listWorkrooms(project.Workrooms, vcsType, vcsSet)
		return nil
	}

	// Neither — list all
	projects, err := s.Config.ProjectsWithWorkrooms()
	if err != nil {
		return err
	}

	if len(projects) == 0 {
		s.say("No workrooms found.")
