		vcsType := s.effectiveVCS(path, proj.VCS, true)
		vcsSet := s.vcsWorkspaceSet(path, vcsType)
		s.listWorkrooms(proj.Workrooms, vcsType, vcsSet)
		s.say("")
	}

	return nil
}

func (s *Service) listWorkrooms(workrooms map[string]config.Workroom, vcsType string, vcsSet map[string]bool) {
	var rows [][]string
	for name, info := range workrooms {
		warnings := s.workroomWarnings(name, info.Path, vcsType, vcsSet)

		row := []string{ui.Bold(name), ui.Dim(ui.DisplayPath(info.Path))}
		if len(warnings) > 0 {
			row = append(row, ui.Yellow(fmt.Sprintf("[%s]", strings.Join(warnings, ", "))))
		}
		rows = append(rows, row)
	}
	ui.PrintTable(s.output(), rows, 2)
