	if _, err := os.Stat(wrPath); os.IsNotExist(err) {
		warnings = append(warnings, "directory not found")
	}
	if vcsSet != nil && !vcsSet[name] && !vcsSet["workroom/"+name] {
		warnings = append(warnings, vcsType+" workspace not found")
