	res, err := svc.CreateNamed(dir, nil)
	if err != nil {
		t.Fatal(err)
	}
	if res.Name != "fixed-name" {
		t.Fatalf("name = %q", res.Name)
	}
	if res.VCS != "jj" {
		t.Fatalf("vcs = %q", res.VCS)
	}
