109	/// history rows). Remote bookmarks are deliberately absent here; push state reads them via
110	/// `origin_tips`.
111	fn bookmark_map(repo: &ReadonlyRepo) -> HashMap<String, Vec<String>> {
112	    let mut map: HashMap<String, Vec<String>> = HashMap::new();
113	    for (name, target) in repo.view().local_bookmarks() {
114	        let label = name.as_symbol().to_string();
115	        for id in target.added_ids() {
116	            map.entry(id.hex()).or_default().push(label.clone());
117	        }
