122	/// The remote whose bookmarks define "pushed". Deliberately just `origin`, not every remote: a commit
123	/// sitting on a stale backup/fork remote is NOT on the project's shared repo, and the badge claims the
124	/// latter. Origin-only also excludes jj's pseudo-remote `git` by construction — in a colocated repo
125	/// every LOCAL git branch is mirrored as `<name>@git` and marked tracked, so counting that remote would
126	/// make every local commit read `Pushed`.
127	const PUSH_REMOTE: &str = "origin";
128	
129	/// `origin`'s tracked, present bookmark tips + their names (for the tooltip scope). Untracked remote
130	/// bookmarks are skipped: jj only reconciles a remote bookmark with its local counterpart while it's
131	/// tracked, so an untracked one says nothing about where local work lives.
132	fn origin_tips(repo: &ReadonlyRepo) -> (Vec<jj_lib::backend::CommitId>, Vec<String>) {
133	    let mut tips = Vec::new();
134	    let mut names = Vec::new();
135	    for (symbol, remote_ref) in repo.view().all_remote_bookmarks() {
136	        if symbol.remote.as_str() != PUSH_REMOTE || !remote_ref.is_tracked() {
137	            continue;
138	        }
139	        if !remote_ref.is_present() {
140	            continue;
141	        }
142	        names.push(format!("{}/{}", PUSH_REMOTE, symbol.name.as_str()));
143	        tips.extend(remote_ref.target.added_ids().cloned());
144	    }
145	    (tips, names)
146	}
