pub fn log_page(root: &Path, limit: usize) -> model::Result<HistoryPage> {
    let (workspace, repo) = open(root)?;
    let store = repo.store();
    let wc_id = repo
        .view()
        .get_wc_commit_id(workspace.workspace_name())
        .cloned();

    let bookmarks = bookmark_map(&repo);
