    let pushed = pushed_revset(repo.as_ref(), &tips);
    let contains = pushed.as_ref().map(|r| r.containing_fn());
    let push_of = |id: &jj_lib::backend::CommitId| match &contains {
        None => model::PushState::Unknown,
