1	//! Integration tests for the per-file ± line counts `changed_files` now returns, against REAL
2	//! throwaway jj repos. Skips if `jj` isn't on PATH — and says so out loud; see
3	//! `tests/common/mod.rs`.
4	//!
5	//! These counts used to be added app-side from a SECOND read — one `jj diff -r @ --stat` process,
6	//! run after the native file list. Three separate defects came out of that split, and the tests below
7	//! pin each one:
8	//!
9	//! 1. `-r @` on a **merge** diffs the auto-merged parents, while the file list is a tree diff against
10	//!    the FIRST parent — so the totals described a different set of files than the rows beside them.
11	//!    A single-parent fixture cannot expose this (the two bases coincide), so
12	//!    `merge_working_copy_counts_against_the_first_parent` needs a real merge — and it asserts jj's own
13	//!    `-r @` number to show the old path really was wrong, not just differently derived.
14	//! 2. Two reads of a moving working copy can disagree; counts now come from the same snapshot as the
15	//!    list, which is what `counts_match_jj_diff_stat_for_a_linear_working_copy` measures against jj.
16	//! 3. A conflicted file's materialized markers count as changed lines. That is *kept* — it's what jj
17	//!    and git both report for the same state — and pinned here so the app's "counts include conflict
18	//!    markers" wording stays true.
19	//!
20	//! `working_status` MUTATES (working-copy lock → snapshot → rewrite `@`), so every fixture is a
21	//! throwaway dir under the temp dir, never a real repo.
22	
23	use std::path::Path;
24	use std::path::PathBuf;
25	use std::process::Command;
26	
27	use wr_vcs_core::model::ChangeKind;
28	use wr_vcs_core::model::ChangedFile;
29	
30	mod common;
31	
32	/// Run `jj` in `dir` with `config` as its ONLY config file. Passed per-`Command` rather than through
33	/// `std::env::set_var`, which would race the other tests in this parallel process.
34	fn jj(args: &[&str], dir: &Path, config: &Path) -> std::process::Output {
35	    Command::new("jj")
36	        .args(args)
37	        .current_dir(dir)
38	        .env("JJ_CONFIG", config)
39	        .output()
40	        .unwrap_or_else(|e| panic!("run jj {args:?}: {e}"))
41	}
42	
43	/// A fresh throwaway repo: unique dir, isolated jj config (supplying an author so snapshot operations
44	/// can commit), `jj git init` run.
45	fn init_repo(tag: &str) -> (PathBuf, PathBuf) {
46	    let dir = std::env::temp_dir().join(format!("wr-stats-{}-{}", std::process::id(), tag));
47	    let _ = std::fs::remove_dir_all(&dir);
48	    std::fs::create_dir_all(&dir).unwrap();
49	    let config = dir.join("jjconfig.toml");
50	    std::fs::write(
51	        &config,
52	        b"[user]\nname = \"Test\"\nemail = \"test@example.com\"\n",
53	    )
54	    .unwrap();
55	    let init = jj(&["git", "init"], &dir, &config);
56	    assert!(
57	        init.status.success(),
58	        "jj git init: {}",
59	        String::from_utf8_lossy(&init.stderr)
60	    );
61	    (dir, config)
62	}
63	
64	fn id_of(rev: &str, dir: &Path, cfg: &Path) -> String {
65	    let out = jj(
66	        &[
67	            "log",
68	            "-r",
69	            rev,
70	            "--no-graph",
71	            "--ignore-working-copy",
72	            "--color",
73	            "never",
74	            "-T",
75	            "commit_id",
76	        ],
77	        dir,
78	        cfg,
79	    );
80	    let id = String::from_utf8_lossy(&out.stdout).trim().to_string();
81	    assert!(!id.is_empty(), "could not resolve {rev}");
82	    id
83	}
84	
85	/// jj's OWN totals for a diff, parsed from `jj diff --stat`'s summary line — the exact string the app
86	/// used to parse app-side. Used here as the cross-check that our native fold agrees with jj where it
87	/// should, and disagrees where jj is answering a different question (`-r @` on a merge).
88	fn jj_stat_totals(args: &[&str], dir: &Path, cfg: &Path) -> (u32, u32) {
89	    let mut full = vec!["diff"];
90	    full.extend_from_slice(args);
91	    full.extend_from_slice(&["--ignore-working-copy", "--stat", "--color", "never"]);
92	    let out = jj(&full, dir, cfg);
93	    let text = String::from_utf8_lossy(&out.stdout);
94	    let summary = text.lines().last().unwrap_or_default();
95	    let count = |suffix: &str| -> u32 {
96	        summary
97	            .split(", ")
98	            .find(|part| part.contains(suffix))
99	            .and_then(|part| part.split_whitespace().next())
100	            .and_then(|n| n.parse().ok())
101	            .unwrap_or(0)
102	    };
103	    (count("insertion"), count("deletion"))
104	}
105	
106	fn file<'a>(files: &'a [ChangedFile], path: &str) -> &'a ChangedFile {
107	    files
108	        .iter()
109	        .find(|f| f.path == path)
110	        .unwrap_or_else(|| panic!("{path} missing from {files:?}"))
111	}
112	
113	/// Sum the rows the way the app's Changes header does. Files with `None` counts (binary, oversized,
114	/// non-file) contribute nothing, matching how git and jj both leave binaries out of a diffstat.
115	fn totals(files: &[ChangedFile]) -> (u32, u32) {
116	    files.iter().fold((0, 0), |(ins, del), f| {
117	        (
118	            ins + f.insertions.unwrap_or(0),
119	            del + f.deletions.unwrap_or(0),
120	        )
121	    })
122	}
123	
124	fn working_files(dir: &Path) -> Vec<ChangedFile> {
125	    wr_vcs_core::working_status(dir)
126	        .expect("working_status")
127	        .working_copy
128	        .files
129	}
130	
131	/// `jj_backend::MAX_COUNTED_BYTES`, mirrored because a private const can't be imported from an
132	/// integration test. Not a duplicate to keep in sync by hand: the two size fixtures below are built
133	/// *from* this value and assert they clear it, so if the backend's cap ever moves upward the fixture
134	/// stops being oversized and its test fails — which is exactly the right failure, since the claim
135	/// being pinned is "content over the cap is not counted".
136	const MAX_COUNTED_BYTES: usize = 4 * 1024 * 1024;
137	
138	/// At least `bytes` of plain, NUL-free text, every line distinct and tagged with `marker`.
139	///
140	/// Distinct lines matter twice over: nothing here may look binary (`looks_binary` would otherwise
141	/// answer before the size check, and the size tests would pass without a size check existing at
142	/// all), and nothing may coincidentally collapse in a diff.
143	///
144	/// Lines are ~512 bytes, which is both realistic and cheap. Realistic because the files that
145	/// actually hit this cap are generated and minified ones — long lines are their shape. Cheap because
146	/// the line count, not the byte count, is what `diff_by_line` and jj's conflict merge scale on:
147	/// at ~80 bytes per line the conflict fixture below spent an extra second tokenizing 50k lines to
148	/// prove nothing the 8k-line version doesn't.
149	fn text_of_size(bytes: usize, marker: &str) -> Vec<u8> {
150	    let filler = "-".repeat(480);
151	    let mut out = Vec::with_capacity(bytes + 128);
152	    let mut n: u64 = 0;
153	    while out.len() < bytes {
154	        out.extend_from_slice(format!("{marker} line {n:012} {filler}\n").as_bytes());
155	        n += 1;
156	    }
157	    assert!(!out.contains(&0), "the fixture must be TEXT, not binary");
158	    out
159	}
160	
161	/// The ordinary case: an edit that adds two lines and removes one.
162	#[test]
163	fn counts_match_a_simple_edit() {
164	    if common::skip_without(&["jj"], "simple-edit stats test") {
165	        return;
166	    }
167	    let (dir, cfg) = init_repo("simple");
168	    std::fs::write(dir.join("a.txt"), b"one\ntwo\nthree\n").unwrap();
169	    jj(&["commit", "-m", "base"], &dir, &cfg);
170	    // one → ONE (a modified line is one deletion + one insertion), plus two appended lines.
171	    std::fs::write(dir.join("a.txt"), b"ONE\ntwo\nthree\nfour\nfive\n").unwrap();
172	
173	    let files = working_files(&dir);
174	    let a = file(&files, "a.txt");
175	    assert_eq!(a.kind, ChangeKind::Modified);
176	    assert_eq!(a.insertions, Some(3), "ONE + four + five; got {a:?}");
177	    assert_eq!(a.deletions, Some(1), "the replaced `one`; got {a:?}");
178	
179	    let _ = std::fs::remove_dir_all(&dir);
180	}
181	
182	/// A whole-file add and a whole-file delete count every line, on the correct side — the absent side of
183	/// the diff has to behave as empty content, not as "uncountable".
184	#[test]
185	fn whole_file_add_and_delete_count_every_line() {
186	    if common::skip_without(&["jj"], "add/delete stats test") {
187	        return;
188	    }
189	    let (dir, cfg) = init_repo("add-delete");
190	    std::fs::write(dir.join("gone.txt"), b"1\n2\n3\n4\n").unwrap();
191	    jj(&["commit", "-m", "base"], &dir, &cfg);
192	    std::fs::remove_file(dir.join("gone.txt")).unwrap();
193	    std::fs::write(dir.join("fresh.txt"), b"a\nb\n").unwrap();
194	
195	    let files = working_files(&dir);
196	    let gone = file(&files, "gone.txt");
197	    assert_eq!(gone.kind, ChangeKind::Deleted);
198	    assert_eq!((gone.insertions, gone.deletions), (Some(0), Some(4)));
199	    let fresh = file(&files, "fresh.txt");
200	    assert_eq!(fresh.kind, ChangeKind::Added);
201	    assert_eq!((fresh.insertions, fresh.deletions), (Some(2), Some(0)));
202	
203	    let _ = std::fs::remove_dir_all(&dir);
204	}
205	
206	/// **The merge defect.** `@` is a clean 2-sided merge: `left` edited `a.txt`, `right` added
207	/// `right.txt`. The file list diffs `@` against its FIRST parent (`left`), so `right.txt` is listed —
208	/// and its lines must be counted.
209	///
210	/// jj's `jj diff -r @` answers a different question (the diff against the auto-merged parents, which
211	/// for a clean merge with no working-copy edits is EMPTY), and that is the number the app used to put
212	/// next to these rows. Asserting both here is what makes this a regression test rather than a
213	/// tautology: ours is non-zero, jj's `-r @` is zero, and ours equals jj's own first-parent-anchored
214	/// stat.
215	#[test]
216	fn merge_working_copy_counts_against_the_first_parent() {
217	    if common::skip_without(&["jj"], "merge stats test") {
218	        return;
219	    }
220	    let (dir, cfg) = init_repo("merge");
221	    std::fs::write(dir.join("a.txt"), b"one\ntwo\n").unwrap();
222	    jj(&["commit", "-m", "base"], &dir, &cfg);
223	    let base = id_of("@-", &dir, &cfg);
224	    // left: edit a.txt
225	    std::fs::write(dir.join("a.txt"), b"ONE\ntwo\n").unwrap();
226	    jj(&["commit", "-m", "left"], &dir, &cfg);
227	    let left = id_of("@-", &dir, &cfg);
228	    // right: add a new file. Addressed by COMMIT ID, never by bookmark — with
229	    // `experimental-advance-branches` on, `jj commit` would advance a bookmark onto the new commit and
230	    // collapse the two sides into one, leaving no merge at all.
231	    jj(&["new", &base, "-m", "right"], &dir, &cfg);
232	    std::fs::write(dir.join("right.txt"), b"r1\nr2\nr3\n").unwrap();
233	    jj(&["commit", "-m", "right"], &dir, &cfg);
234	    let right = id_of("@-", &dir, &cfg);
