403	/// One unreadable BLOB degrades that one row — it must not fail the whole read.
404	///
405	/// Counting lines is what made this reachable: the tree diff `changed_files` replaced only ever read
406	/// tree objects, whereas materializing content reads the file's blob on both sides. jj-lib folds a
407	/// content failure into the same `entry.values` error as a tree failure, so treating every error as
408	/// `PartialData` meant a single missing object (blobless/partial clone, a pruned object, a gc/repack
409	/// race) took out the entire status read — and Swift maps `.partialData` to `.notRepository`, so the
410	/// sidebar and the Changes panel both claimed the workroom wasn't a repository at all.
411	///
412	/// The blob is deleted straight out of jj's backing git store, which is what a pruned object IS.
413	#[test]
414	fn an_unreadable_blob_degrades_one_row_not_the_whole_read() {
415	    // `git` as well as `jj`: the damage is inflicted with the git CLI, straight into jj's store.
416	    if common::skip_without(&["jj", "git"], "unreadable-blob test") {
417	        return;
418	    }
419	    let (dir, cfg) = init_repo("unreadable-blob");
420	    std::fs::write(dir.join("a.txt"), b"one\ntwo\nthree\n").unwrap();
421	    std::fs::write(dir.join("b.txt"), b"untouched\n").unwrap();
422	    jj(&["commit", "-m", "base"], &dir, &cfg);
423	    std::fs::write(dir.join("a.txt"), b"ONE\ntwo\nthree\nfour\n").unwrap();
424	    std::fs::write(dir.join("b.txt"), b"untouched\nplus one\n").unwrap();
425	
426	    // jj's backing git repo, via the `git_target` pointer rather than a hardcoded path (it's
427	    // relative to the store dir, and differs between a colocated repo and this one).
428	    let store_dir = dir.join(".jj/repo/store");
429	    let target = std::fs::read_to_string(store_dir.join("git_target")).unwrap();
430	    let store = std::fs::canonicalize(store_dir.join(target.trim())).unwrap();
431	    let git = |args: &[&str]| {
432	        Command::new("git")
433	            .arg("--git-dir")
434	            .arg(&store)
435	            .args(args)
436	            .output()
437	            .unwrap_or_else(|e| panic!("run git {args:?}: {e}"))
438	    };
439	    // `ls-tree`, not `rev-parse <commit>:a.txt` — with no work tree, rev-parse reads that form as a
440	    // path and fails. Output is `<mode> blob <sha>\t<path>`.
441	    let parent = id_of("@-", &dir, &cfg);
442	    let listed = git(&["ls-tree", &parent, "a.txt"]);
443	    let listed = String::from_utf8_lossy(&listed.stdout);
444	    let blob = listed.split_whitespace().nth(2).unwrap_or_default();
445	    assert_eq!(
446	        blob.len(),
447	        40,
448	        "could not resolve the parent blob for a.txt from {listed:?}"
449	    );
450	    let object = store.join("objects").join(&blob[..2]).join(&blob[2..]);
451	    assert!(object.exists(), "expected a loose object at {object:?}");
452	    std::fs::remove_file(&object).unwrap();
453	
454	    let status =
455	        wr_vcs_core::working_status(&dir).expect("one missing blob must not fail the read");
456	    assert!(status.is_dirty(), "the working copy is still dirty");
457	    let files = status.working_copy.files;
458	
459	    // The damaged file keeps its row and its real kind; only the counts go missing — which is
460	    // already what `None` means here (binary, oversized, unreadable).
461	    let a = file(&files, "a.txt");
462	    assert_eq!(a.kind, ChangeKind::Modified, "kind survives; got {a:?}");
463	    assert_eq!(
464	        (a.insertions, a.deletions),
465	        (None, None),
466	        "an unreadable blob can't be counted; got {a:?}"
467	    );
468	    // …and the file beside it is unaffected, counts included.
469	    let b = file(&files, "b.txt");
470	    assert_eq!((b.insertions, b.deletions), (Some(1), Some(0)), "got {b:?}");
471	    assert_eq!(totals(&files), (1, 0));
472	
473	    let _ = std::fs::remove_dir_all(&dir);
474	}
