530	/// One side of the conflict fixture below. Under the cap on its own, deliberately — see the test.
531	const CONFLICT_SIDE_BYTES: usize = (MAX_COUNTED_BYTES / 8) * 3;
532	
533	/// The two properties the conflict fixture's design rests on, checked at COMPILE time — they're
534	/// constants, so this is a build error rather than a test failure if either ever flips (and clippy
535	/// rightly refuses a runtime `assert!` on a constant). Between them they say: no single side can be
536	/// the reason the counts come back `None`, but the materialized markers that embed all three must
537	/// be. Get the first wrong and the plain `File` arm answers for the before-side, the conflict arm is
538	/// never consulted, and the test passes with the code under test deleted — which is exactly what the
539	/// first draft of it did.
540	const _: () = {
541	    assert!(
542	        CONFLICT_SIDE_BYTES < MAX_COUNTED_BYTES,
543	        "each conflict side must be UNDER the cap on its own"
544	    );
545	    assert!(
546	        3 * CONFLICT_SIDE_BYTES > MAX_COUNTED_BYTES,
547	        "…but the three sides the materialized markers embed must together exceed it"
548	    );
549	};
