551	/// A CONFLICTED file whose MATERIALIZED text is over the cap reports `None` too — the arm that had no
552	/// size check at all.
553	///
554	/// `conflicted_file_counts_its_materialized_markers` pins the opposite for a small conflict (it IS
555	/// counted, markers and all), so until now the conflict arm's only bound was `looks_binary`: a
556	/// multi-megabyte conflicted lockfile got read, merged and line-diffed whole on every 15s status
557	/// sweep, per workroom.
558	///
559	/// **The fixture's whole design is about not testing the wrong arm.** `line_stats` short-circuits on
560	/// the FIRST side that yields `None`, and the *before* side here is a plain `File` — `@`'s first
561	/// parent, `left`. Sizing the sides at 4 MiB each (the obvious way to build an oversized conflict)
562	/// makes `left` alone breach the cap, so the `File` arm answers, the conflict arm is never consulted,
563	/// and the test passes whether or not the check under test exists. Confirmed the hard way: the first
564	/// draft did exactly that and stayed green with the check deleted.
565	///
566	/// So each side is kept comfortably UNDER the cap, and it's their SUM that goes over: with all three
567	/// sides mutually different, the whole file is one conflicting region, and a materialized region
568	/// carries every side (`marker-style = "diff"` renders base→left as a diff, then right in full).
569	/// Three × 1.5 MiB ⇒ ~4.5 MiB of markers out of 1.5 MiB inputs — only the conflict arm can see that.
570	#[test]
571	fn a_conflicted_file_over_the_size_cap_reports_no_counts() {
572	    if common::skip_without(&["jj"], "oversized-conflict stats test") {
573	        return;
574	    }
575	    let (dir, cfg) = init_repo("oversized-conflict");
576	    // Track both files while they're small (see the `max_new_file_size` note above), then grow
577	    // `f.txt` in a commit of its own — that commit is the conflict's base.
578	    std::fs::write(dir.join("f.txt"), b"seed\n").unwrap();
579	    std::fs::write(dir.join("note.txt"), b"one\n").unwrap();
580	    jj(&["commit", "-m", "seed"], &dir, &cfg);
581	
582	    // Three mutually different bodies: every line differs on every side, so the merge finds no
583	    // common ground and the conflicting region is the entire file.
584	    std::fs::write(dir.join("f.txt"), text_of_size(CONFLICT_SIDE_BYTES, "base")).unwrap();
585	    jj(&["commit", "-m", "base"], &dir, &cfg);
586	    let base = id_of("@-", &dir, &cfg);
587	
588	    std::fs::write(dir.join("f.txt"), text_of_size(CONFLICT_SIDE_BYTES, "left")).unwrap();
589	    jj(&["commit", "-m", "left"], &dir, &cfg);
590	    let left = id_of("@-", &dir, &cfg);
591	    // By commit id, never by bookmark — `experimental-advance-branches` would otherwise collapse the
592	    // two sides and leave no merge (the same reason the other merge fixtures here do this).
593	    jj(&["new", &base, "-m", "right"], &dir, &cfg);
594	    std::fs::write(
595	        dir.join("f.txt"),
596	        text_of_size(CONFLICT_SIDE_BYTES, "right"),
597	    )
598	    .unwrap();
599	    jj(&["commit", "-m", "right"], &dir, &cfg);
600	    let right = id_of("@-", &dir, &cfg);
601	    jj(&["new", &left, &right], &dir, &cfg);
602	    // An ordinary edit alongside it, so "nothing was counted" can't be trivially true of the read.
603	    std::fs::write(dir.join("note.txt"), b"one\ntwo\n").unwrap();
604	
605	    let files = working_files(&dir);
606	    let f = file(&files, "f.txt");
607	    assert_eq!(
608	        f.kind,
609	        ChangeKind::Conflicted,
610	        "the fixture must actually be conflicted, or this measures nothing; got {files:?}"
611	    );
612	    assert_eq!(
613	        (f.insertions, f.deletions),
614	        (None, None),
615	        "an oversized conflict is not counted, materialized markers or not; got {f:?}"
616	    );
617	    assert_eq!(file(&files, "note.txt").insertions, Some(1));
618	    assert_eq!(totals(&files), (1, 0));
619	
620	    let _ = std::fs::remove_dir_all(&dir);
621	}
