static func ci(_ s: WorkroomStatus) -> CIGlyph? {
  guard let ci = s.ci else { return nil }
  switch ci {
  case .passing:
    return CIGlyph(
      symbol: "checkmark.circle.fill", semantic: .ciPass, accessibility: "CI passing")
  case .failing:
